ee:message.ee:set-payload:
%dw 2.0
output application/json  
---
{
  codeResponse: "200",
  messageResponse: "OK",
  accounts: [
    {
      accountNumber: vars.billingAccount,
      balances: payload.result.result.balDtoList map ((item, index) -> {
        balanceId: item.balID,
        balanceTypeCode: item.acctResCode,
        balanceTypeName: item.acctResName,
        balance: item.balance,
        effectiveDate: item.effDate,
        expirationDate: item.expDate,
        lastUpdateDate: item.updateDate
      })
    }
  ]
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "MDM_CUENTA_FACTURACION",
			"pipeline": [{
				"\$match": {
					"Tipo_Documento": vars.billingParams.'CUSTOMER_ID_TYPE',
					"Numero_Documento": vars.billingParams.'CUSTOMER_ID',
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
	basePath: p("zsmart-sapi.base-path"),
	host: p("zsmart-sapi.host"),
	port: p("zsmart-sapi.port"),
	method: "GET",
	path: p('zsmart-sapi.resources.billingBalance.path'),
	body: {
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
		"msisdn": vars.billingParams.'CONNECTION_NUMBER',
		"accountCode": vars.mdmCuentaFact.result[0]."Numero_Cuenta",
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json  
---
{
  codeResponse: "200",
  messageResponse: "OK",
  accounts: [
    {
      accountNumber: vars.billingAccount,
      balances: payload.result.result.balDtoList map ((item, index) -> {
        balanceId: item.balID,
        balanceTypeCode: item.acctResCode,
        balanceTypeName: item.acctResName,
        balance: item.balance,
        effectiveDate: item.effDate,
        expirationDate: item.expDate,
        lastUpdateDate: item.updateDate
      })
    }
  ]
}

%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "BILLING_BALANCE:INVALID_PARAMS",
    "message": "At least 'BILLING_ACCOUNT' or both 'CUSTOMER_ID_TYPE' and 'CUSTOMER_ID' must be provided.",
    "messageServer": error.description,
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": "At least 'BILLING_ACCOUNT' or both 'CUSTOMER_ID_TYPE' and 'CUSTOMER_ID' must be provided."
        }
    ]
}
